export type ReceiveStripeWebhookData = {
    /**
     * The Stripe event, unmodified. The body is hashed exactly as it arrives, so it is never re-serialized before verification.
     */
    body: StripeEvent;
    headers: {
        /**
         * Stripe's signature over the exact request bytes, in the form `t=<unix seconds>,v1=<hex hmac-sha256>`. The HMAC is computed over `<timestamp>.<raw body>` keyed with the endpoint's signing secret. More than one `v1` may be present, which is how a rotation is absorbed.
         */
        'Stripe-Signature': string;
    };
    path?: never;
    query?: never;
    url: '/v1/webhooks/stripe';
};

export type ReceiveStripeWebhookErrors = {
    /**
     * The signature did not verify, the signature header was missing, or the body was not an event. Nothing is stored. 400 rather than 422 because the sender could not have known its signing secret was wrong, and rather than 5xx because a retry would fail identically.
     */
    400: Problem;
    /**
     * No signing secret is configured, so no signature can be checked. This is this service's misconfiguration and never the sender's fault; the body deliberately does not say the signature was invalid, because that would send an operator looking in the wrong place. The cause is logged.
     */
    503: Problem;
};

export type ReceiveStripeWebhookError = ReceiveStripeWebhookErrors[keyof ReceiveStripeWebhookErrors];

export type ReceiveStripeWebhookResponses = {
    /**
     * The event was verified and is recorded. Whatever became of it — emitted, deliberately ignored, or parked as failed — the processor has nothing to retry.
     * There is no response body. The processor is told only that the event was received; what this service did with it is a fact about billing's own tables, and inventing a body here would be a response shape with no contract behind it. What became of the event is queryable: `processor_webhooks.error` carries `ignored:<reason>` or `failed:<class>: <message>`, and a NULL `processed_at` is the only state a crash can leave behind.
     */
    200: unknown;
};
